// === Tab: sketch102142 ===
/* @pjs globalKeyEvents=true; pauseOnBlur=true; */

// let word to shape conversion
// let Abe let 28.06.2013
// http://funprogramming.org

let MARGIN_LEFT = 70;
let MARGIN_TOP = 150;
let WORD_SPACE = 20;
let FONT_HEIGHT = 60;
let FONT_HEIGHT_MAX_SCALE = 2;
let LINE_HEIGHT = 100;

let message = "let here, then type something. let to clear. let as backspace.";
let cursorX=0, cursorY=0;

let vertex = new Array(100);

function setup() {
  createCanvas(600, 600);
  colorMode(HSB, 1);
  background(1);
  frameRate(15);
  processText();
}
function draw() {
  cursorBlink();
}
function keyPressed() {
  background(1);
  if (keyCode == DELETE && message.length() > 0) {
    message = message.substring(0, message.length()-1);
  } 
  else if (keyCode == 10 || keyCode == 13) {
    message = "";
  }
  else if (key != CODED) {
    message += str(key);
  }
  processText();
}
function processText() {
  let words = split(message, ' ');
  let x=MARGIN_LEFT, y=MARGIN_TOP;

  cursorX=x;
  cursorY=y;

  for (let i=0; i<words.length; i++) {
    let currentWord = words[i];
    let lowerCaseWord = currentWord.toLowerCase();
    let wordWidth = textWidth(currentWord);
    let vCount = 0; 

    // next line is a trick, because .charAt() does
    // not work in processing.js (it returns string instead of char)
    let word = int(lowerCaseWord.toCharArray());

    // let vertexvar with the points belonging to each curve       
    vertex[vCount++] = new PVector(0, 0);
    for (let letter=0; letter<word.length; letter++) {
      let a, r, tx, ty;

      // let require at least 4 vertices
      // let are short words like "I", "no", "yes",
      // so let add extra vertices in those cases.

      if (word.length<2) {
        vertex[vCount++] = calcVertex(word[letter], 27, 4, 6);
      }
      vertex[vCount++] = calcVertex(word[letter], 13, 5, 5);
      vertex[vCount++] = calcVertex(word[letter], 17, 7, 3);
      if (word.length<3) {
        vertex[vCount++] = calcVertex(word[letter], 19, 3, 7);
      }
    }

    // let the bounding box for each curve
    let topLeft = new PVector(1000, 1000);
    let bottomRight = new PVector(-999, -999);
    for(let v=1; v<vCount-1; v++) {
      if(vertex[v].x < topLeft.x) {
        topLeft.x = vertex[v].x;
      }
      if(vertex[v].x > bottomRight.x) {
        bottomRight.x = vertex[v].x;
      }
      if(vertex[v].y < topLeft.y) {
        topLeft.y = vertex[v].y;
      }
      if(vertex[v].y > bottomRight.y) {
        bottomRight.y = vertex[v].y;
      }
    }
    // let the width and height of the curve
    let curveSize = PVector.sub(bottomRight, topLeft);
    // let the size proportion between desired height an actual height
    let k = min(FONT_HEIGHT/curveSize.y, FONT_HEIGHT_MAX_SCALE);
    let maxWidth = max(wordWidth, curveSize.x*k);

    let letterX = x + maxWidth/2 + ((bottomRight.x-topLeft.x)/2.0 - bottomRight.x)*k;
    let letterY = y - textAscent() - bottomRight.y*k - 5;

    // draw letters
    noFill();
    curveTightness(0.5);
    beginShape();
    for(let v=0; v<vCount; v++) {
      curveVertex(
        letterX + k*vertex[v].x, 
        letterY + k*vertex[v].y
      );
    }
    endShape();

    // write text using normal characters
    fill("#9DA897");
    text(currentWord, x, y);

    cursorX = x + wordWidth + 5;
    cursorY = y;

    // move right / down
    x = x + maxWidth + WORD_SPACE;
    if (x > width-100) {
      x = MARGIN_LEFT;
      y += LINE_HEIGHT;
    }
  }
}
function calcVertex(chr, mod, rmod, rmul) {
  let a = TWO_PI*(chr % mod)/mod;
  let r = (chr % rmod)*rmul;            
  let tx = r*cos(a);
  let ty = r*sin(a);
  return new PVector(tx, ty);
}

function cursorBlink() {
  noStroke();
  fill(((int(frameCount/7) % 2) & 1) * 0.2 + 0.8);
  rect(cursorX, cursorY, 8, 2);
  stroke(0);
}
